"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from "recharts";
import { ArrowDownRight, ArrowUpRight, Bell, ChevronLeft, ChevronRight, CircleDollarSign, CloudOff, CreditCard, LayoutDashboard, ListFilter, LogOut, Menu, Pencil, Plus, RefreshCw, Search, Settings2, Sparkles, Trash2, WalletCards, WifiOff, X } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { NativeSelect } from "@/components/ui/native-select";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Toaster } from "@/components/ui/sonner";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";

type View = "overview" | "transactions" | "cards" | "automation";
type Modal = "transaction" | "card" | "category" | "subcategory" | "rule" | null;
type Category = { id: string; name: string; color: string; icon: string; kind: string };
type Subcategory = { id: string; categoryId: string; name: string };
type Card = { id: string; bank: string; brand: string; last4: string; cardType: string; alias: string | null };
type Rule = { id: string; name: string; field: string; operator: string; pattern: string; categoryId: string; subcategoryId: string | null; priority: number; enabled: boolean };
type Transaction = { id: string; merchant: string; description: string | null; amountCents: number; currency: string; operationDate: number; operationType: string; bank: string; cardId: string | null; categoryId: string | null; subcategoryId: string | null; category: string; source: string; maskedCard: string | null; classification?: string | null; confidenceLevel?: "high" | "medium" | null; decisionReason?: string | null };
type Recurring = { merchant: string; kind: "subscription" | "possible"; months: number; medianCents: number; currency: string; lastDate: number; cadenceDays: number | null; cardLabel: string | null; confidence: number; activeInPeriod: boolean };
type Totals = { expensesCents: number; incomeCents: number; transfersCents: number; refundsCents: number; subscriptionsCents: number; balanceCents: number; transactionCount: number };
type Snapshot = {
  user: { email: string; name: string }; account: { email: string; lastSyncAt: number | null } | null;
  latestSync: { status: string; transactionsCreated: number; parseFailures: number; startedAt: number; finishedAt: number | null } | null;
  summary: { currentMonthCents: number; todayCents: number; previousMonthCents: number; transactionCount: number };
  trend: Array<{ day: string; current: number; previous: number }>; byBank: Array<{ name: string; value: number }>; byCard: Array<{ name: string; value: number }>; byCategory: Array<{ name: string; value: number }>;
  categories: Category[]; subcategories: Subcategory[]; cards: Card[]; rules: Rule[]; banks: string[]; transactions: Transaction[];
  period?: { month: string; start: number; end: number }; otherCurrencies?: Array<{ currency: string; expensesCents: number; incomeCents: number; count: number }>; availableMonths?: string[]; totals?: Totals; byMerchant?: Array<{ name: string; value: number }>; recurring?: Recurring[];
};

const currentMonthKey = () => { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`; };
const monthLabel = (value: string) => { const [year, month] = value.split("-").map(Number); const text = new Intl.DateTimeFormat("es-PE", { month: "long", year: "numeric" }).format(new Date(year, month - 1, 1)); return text.charAt(0).toUpperCase() + text.slice(1); };

const palette = ["#2bd9a8", "#625cf6", "#efb444", "#ff7f6e", "#4a8fe7", "#a96fe8"];
const money = (cents: number, currency = "PEN") => new Intl.NumberFormat("es-PE", { style: "currency", currency }).format(cents / 100);
const dateText = (value: number) => new Intl.DateTimeFormat("es-PE", { day: "2-digit", month: "short", year: "numeric" }).format(value);
const inputDate = (value?: number) => new Date(value ?? Date.now()).toISOString().slice(0, 10);

async function jsonRequest<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  const body = response.status === 204 ? null : await response.json().catch(() => null) as { error?: string; code?: string } | null;
  if (response.status === 401) { window.location.replace("/"); throw new Error("Tu sesión expiró."); }
  if (!response.ok) throw Object.assign(new Error(body?.error || "No se pudo completar la operación."), { code: (body as { code?: string } | null)?.code });
  return body as T;
}

export function ProductClient() {
  const [view, setView] = useState<View>("overview");
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState("");
  const [online, setOnline] = useState(true);
  const [mounted, setMounted] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [needsReconnect, setNeedsReconnect] = useState(false);
  const [period, setPeriod] = useState(currentMonthKey); // mes seleccionado, YYYY-MM
  const [query, setQuery] = useState("");
  const [bank, setBank] = useState("");
  const [cardId, setCardId] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [modal, setModal] = useState<Modal>(null);
  const [editing, setEditing] = useState<Transaction | Card | Category | Subcategory | Rule | null>(null);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    const params = new URLSearchParams();
    params.set("month", period); if (query.trim()) params.set("q", query.trim()); if (bank) params.set("bank", bank); if (cardId) params.set("cardId", cardId); if (categoryId) params.set("categoryId", categoryId);
    try {
      const response = await fetch(`/api/bootstrap?${params}`, { cache: "no-store" });
      if (response.status === 401) { window.location.replace("/"); return; }
      const body = await response.json() as Snapshot & { error?: string };
      if (!response.ok) throw new Error(body.error || "No se pudieron cargar tus datos.");
      setSnapshot(body); setError("");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudieron cargar tus datos."); }
    finally { setLoading(false); }
  }, [period, query, bank, cardId, categoryId]);

  useEffect(() => { const frame = requestAnimationFrame(() => { setMounted(true); setOnline(navigator.onLine); }); const up = () => { setOnline(true); void load(true); }; const down = () => setOnline(false); addEventListener("online", up); addEventListener("offline", down); return () => { cancelAnimationFrame(frame); removeEventListener("online", up); removeEventListener("offline", down); }; }, [load]);
  useEffect(() => { const timer = window.setTimeout(() => void load(), query ? 350 : 0); return () => clearTimeout(timer); }, [load, query]);

  const sync = async () => {
    if (!online) { toast.error("No tienes conexión"); return; }
    setSyncing(true);
    try {
      // Cada ejecución procesa un lote acotado; se repite sola hasta terminar (máx. 40 rondas) para no obligar a pulsar varias veces.
      let created = 0, discarded = 0, more = false;
      for (let round = 0; round < 40; round++) {
        const result = await jsonRequest<{ created: number; duplicates: number; failures: number; remaining: number; hasMore: boolean }>("/api/sync", { method: "POST" });
        created += result.created; discarded += result.failures; more = result.hasMore;
        if (round % 3 === 2 || !more) await load(true);
        if (!more || (result.created === 0 && result.failures === 0)) break;
      }
      await load(true);
      toast.success(created ? `${created} movimientos nuevos` : "Gmail ya está al día", { description: more ? "Aún quedan correos por revisar: vuelve a sincronizar." : discarded ? `${discarded} correos descartados (publicidad u otros sin operación real).` : "Sin duplicados." });
    }
    catch (cause) { if ((cause as { code?: string }).code === "reconnect_required") setNeedsReconnect(true); toast.error("No pudimos sincronizar", { description: cause instanceof Error ? cause.message : "Inténtalo otra vez." }); }
    finally { setSyncing(false); }
  };

  const mutate = async (url: string, init: RequestInit, success: string) => {
    try { await jsonRequest(url, { ...init, headers: { "content-type": "application/json", ...(init.headers || {}) } }); setModal(null); setEditing(null); await load(true); toast.success(success); }
    catch (cause) { toast.error(cause instanceof Error ? cause.message : "No se pudo guardar."); }
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("auth") !== "connected") return;
    toast.success("Gmail conectado", { description: "Pulsa Sincronizar Gmail para importar tus movimientos." });
    window.history.replaceState(null, "", window.location.pathname);
  }, []);
  const logout = async () => { await fetch("/api/auth/logout", { method: "POST" }); window.location.replace("/"); };
  const open = (kind: Exclude<Modal, null>, item: Transaction | Card | Category | Subcategory | Rule | null = null) => { setEditing(item); setModal(kind); };
  const changeRule = async (rule: Rule, enabled: boolean) => mutate(`/api/rules/${rule.id}`, { method: "PATCH", body: JSON.stringify({ enabled }) }, enabled ? "Regla activada" : "Regla pausada");
  const current = (snapshot?.summary.currentMonthCents || 0); const previous = snapshot?.summary.previousMonthCents || 0; const change = previous ? ((current - previous) / previous) * 100 : null;

  if (loading && !snapshot) return <AppSkeleton />;
  if (error && !snapshot) return <FatalState online={online} message={error} retry={() => void load()} />;

  return <div className="min-h-screen bg-[#eef2f4] pb-20 text-[#10231e] lg:pb-0">
    <Toaster position="top-right" richColors />
    {!online && <div className="fixed inset-x-0 top-0 z-[70] flex h-8 items-center justify-center gap-2 bg-[#9a392f] text-xs font-semibold text-white"><WifiOff className="size-3.5"/> Sin conexión. Tus datos no se actualizarán.</div>}
    <aside className={`fixed inset-y-0 left-0 z-50 hidden w-[244px] flex-col bg-[#102820] px-4 py-5 text-white lg:flex ${!online ? "pt-12" : ""}`}><Brand /><nav className="mt-8 space-y-1.5"><Nav active={view === "overview"} icon={<LayoutDashboard/>} label="Resumen" onClick={() => setView("overview")}/><Nav active={view === "transactions"} icon={<CreditCard/>} label="Movimientos" onClick={() => setView("transactions")}/><Nav active={view === "cards"} icon={<WalletCards/>} label="Tarjetas" onClick={() => setView("cards")}/><Nav active={view === "automation"} icon={<Settings2/>} label="Categorías y reglas" onClick={() => setView("automation")}/></nav><div className="mt-auto rounded-[20px] border border-white/10 bg-white/[.06] p-4"><p className="text-xs text-white/45">Cuenta conectada</p><p className="mt-1 truncate text-sm font-semibold">{snapshot?.account?.email}</p><button onClick={logout} className="mt-4 flex items-center gap-2 text-xs text-white/55 hover:text-white"><LogOut className="size-3.5"/> Cerrar sesión</button></div></aside>
    <main className="min-h-screen lg:pl-[244px]">
      <header className={`sticky z-30 flex h-[72px] items-center border-b border-[#dce3e1] bg-[#f8faf9]/90 px-4 backdrop-blur-xl sm:px-7 lg:px-9 ${online ? "top-0" : "top-8"}`}><button className="mr-3 rounded-xl p-2 lg:hidden" onClick={() => setMobileMenu(!mobileMenu)} aria-label="Abrir navegación"><Menu className="size-5"/></button><div><p className="text-xs font-semibold text-[#71807b]">{view === "overview" ? "Panorama financiero" : view === "transactions" ? "Todos tus movimientos" : view === "cards" ? "Medios de pago" : "Automatización"}</p><p className="font-semibold tracking-[-.025em]">{snapshot?.user.name}</p></div><div className="ml-auto flex items-center gap-2">{snapshot?.account?.lastSyncAt && <span className="hidden text-xs text-[#75847f] md:inline">Actualizado {new Intl.DateTimeFormat("es-PE", { hour: "2-digit", minute: "2-digit" }).format(snapshot.account.lastSyncAt * 1000)}</span>}<Button onClick={sync} disabled={syncing || !online} size="sm" className="h-9 rounded-xl bg-[#173d32] text-white"><RefreshCw className={`size-4 ${syncing ? "animate-spin" : ""}`}/><span className="hidden sm:inline">{syncing ? "Sincronizando" : "Sincronizar Gmail"}</span></Button><button className="grid size-9 place-items-center rounded-xl border bg-white" aria-label="Notificaciones"><Bell className="size-4"/></button></div></header>
      {mobileMenu && <div className="border-b bg-[#102820] p-3 text-white lg:hidden"><div className="grid grid-cols-2 gap-2"><Nav active={view === "overview"} icon={<LayoutDashboard/>} label="Resumen" onClick={() => { setView("overview"); setMobileMenu(false); }}/><Nav active={view === "transactions"} icon={<CreditCard/>} label="Movimientos" onClick={() => { setView("transactions"); setMobileMenu(false); }}/><Nav active={view === "cards"} icon={<WalletCards/>} label="Tarjetas" onClick={() => { setView("cards"); setMobileMenu(false); }}/><Nav active={view === "automation"} icon={<Settings2/>} label="Reglas" onClick={() => { setView("automation"); setMobileMenu(false); }}/></div><button onClick={logout} className="mt-3 flex items-center gap-2 px-2 py-2 text-sm text-white/70 hover:text-white"><LogOut className="size-4"/> Cerrar sesión</button></div>}
      {needsReconnect && <div role="alert" className="flex flex-wrap items-center justify-center gap-3 bg-[#fff3f0] px-4 py-3 text-sm text-[#823f35]">Lúmina perdió el acceso a tu Gmail. <a href="/api/auth/google/start" className="font-semibold underline">Reconectar Gmail</a></div>}
      <div className="mx-auto max-w-[1500px] px-4 py-6 sm:px-7 lg:px-9 lg:py-8">
        {view === "overview" && <><DashboardFilters snapshot={snapshot!} period={period} setPeriod={setPeriod} bank={bank} setBank={setBank} cardId={cardId} setCardId={setCardId} categoryId={categoryId} setCategoryId={setCategoryId}/><Overview snapshot={snapshot!} mounted={mounted} change={change} sync={sync} add={() => open("transaction")} />{snapshot!.transactions.length > 0 && <BreakdownPanels bank={snapshot!.byBank} card={snapshot!.byCard} merchant={snapshot!.byMerchant ?? []}/>}{(snapshot!.recurring?.length ?? 0) > 0 && <RecurringPanel items={snapshot!.recurring ?? []}/>}</>}
        {view === "transactions" && <TransactionsView snapshot={snapshot!} query={query} setQuery={setQuery} period={period} setPeriod={setPeriod} bank={bank} setBank={setBank} cardId={cardId} setCardId={setCardId} categoryId={categoryId} setCategoryId={setCategoryId} add={() => open("transaction")} edit={(item) => open("transaction", item)} remove={(id) => mutate(`/api/transactions/${id}`, { method: "DELETE" }, "Movimiento eliminado")} sync={sync} />}
        {view === "cards" && <CardsView snapshot={snapshot!} add={() => open("card")} edit={(item) => open("card", item)} remove={(id) => mutate(`/api/cards/${id}`, { method: "DELETE" }, "Tarjeta eliminada")} />}
        {view === "automation" && <><AutomationView snapshot={snapshot!} addCategory={() => open("category")} editCategory={(item) => open("category", item)} removeCategory={(id) => mutate(`/api/categories/${id}`, { method: "DELETE" }, "Categoría eliminada")} addRule={() => open("rule")} editRule={(item) => open("rule", item)} removeRule={(id) => mutate(`/api/rules/${id}`, { method: "DELETE" }, "Regla eliminada")} changeRule={changeRule} /><SubcategoriesPanel snapshot={snapshot!} add={() => open("subcategory")} edit={(item) => open("subcategory", item)} remove={(id) => mutate(`/api/subcategories/${id}`, { method: "DELETE" }, "Subcategoría eliminada")} /></>}
      </div>
    </main>
    <nav className="fixed inset-x-3 bottom-3 z-40 grid grid-cols-4 rounded-[22px] border border-white/40 bg-[#102820]/95 p-1.5 text-white shadow-2xl backdrop-blur-xl lg:hidden" aria-label="Navegación inferior"><Bottom active={view === "overview"} icon={<LayoutDashboard/>} label="Resumen" onClick={() => setView("overview")}/><Bottom active={view === "transactions"} icon={<CreditCard/>} label="Movimientos" onClick={() => setView("transactions")}/><Bottom active={view === "cards"} icon={<WalletCards/>} label="Tarjetas" onClick={() => setView("cards")}/><Bottom active={view === "automation"} icon={<Settings2/>} label="Reglas" onClick={() => setView("automation")}/></nav>
    <EntityDialog modal={modal} editing={editing} snapshot={snapshot!} close={() => { setModal(null); setEditing(null); }} save={mutate} />
  </div>;
}

function Overview({ snapshot, mounted, change, sync, add }: { snapshot: Snapshot; mounted: boolean; change: number | null; sync: () => void; add: () => void }) {
  const hasData = snapshot.transactions.length > 0;
  const totals = snapshot.totals ?? { expensesCents: snapshot.summary.currentMonthCents, incomeCents: 0, transfersCents: 0, refundsCents: 0, subscriptionsCents: 0, balanceCents: -snapshot.summary.currentMonthCents, transactionCount: snapshot.summary.transactionCount };
  return <><div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-sm font-semibold text-[#71807b]">{snapshot.period && snapshot.period.month !== currentMonthKey() ? monthLabel(snapshot.period.month) : "Este mes"}</p><h1 className="mt-1 text-3xl font-semibold tracking-[-.055em] sm:text-5xl">Tu dinero, sin puntos ciegos.</h1></div><Button variant="outline" className="w-fit rounded-xl bg-white" onClick={add}><Plus/>Movimiento manual</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Kpi label="Gastos del mes" value={money(snapshot.summary.currentMonthCents)} note={change === null ? "Sin mes anterior para comparar" : `${Math.abs(change).toFixed(1)}% ${change <= 0 ? "menos" : "más"} que el mes anterior`} positive={change !== null && change <= 0} icon={<CircleDollarSign/>}/><Kpi label="Ingresos" value={money(totals.incomeCents)} note="Abonos y depósitos del mes" icon={<ArrowDownRight/>}/><Kpi label="Balance" value={money(totals.balanceCents)} note="Ingresos + reembolsos − gastos" positive={totals.balanceCents >= 0} icon={<ArrowUpRight/>}/><Kpi label="Suscripciones" value={money(totals.subscriptionsCents)} note="Cobros recurrentes detectados" icon={<RefreshCw/>}/><Kpi label="Transferencias" value={money(totals.transfersCents)} note="No se suman al gasto" icon={<ArrowUpRight/>}/><Kpi label="Movimientos" value={String(snapshot.summary.transactionCount)} note="Confirmados en este mes" icon={<CreditCard/>}/></div>{(snapshot.otherCurrencies?.length ?? 0) > 0 && <p className="mt-3 rounded-xl border border-[#e3ebe8] bg-white px-4 py-3 text-sm text-[#5d6e68]">Los totales están en soles. Otras monedas este mes (no se suman): {snapshot.otherCurrencies!.map((item) => [item.expensesCents ? `${money(item.expensesCents, item.currency)} en gastos` : "", item.incomeCents ? `${money(item.incomeCents, item.currency)} en ingresos` : ""].filter(Boolean).join(" y ") + ` (${item.count} mov.)`).join(" · ")}.</p>}{!hasData ? <Empty className="panel mt-4 min-h-[420px] border"><EmptyHeader><EmptyMedia variant="icon"><Sparkles/></EmptyMedia><EmptyTitle>Tu dashboard está listo para recibir datos</EmptyTitle><EmptyDescription>Sincroniza Gmail para detectar tus movimientos bancarios o agrega el primero manualmente.</EmptyDescription></EmptyHeader><EmptyContent><div className="flex flex-col gap-2 sm:flex-row"><Button onClick={sync} className="rounded-xl"><RefreshCw/>Sincronizar Gmail</Button><Button onClick={add} variant="outline" className="rounded-xl"><Plus/>Agregar manualmente</Button></div></EmptyContent></Empty> : <div className="mt-4 grid gap-4 xl:grid-cols-[1.55fr_.8fr]"><section className="panel p-5 sm:p-6"><p className="section-label">Evolución</p><h2 className="mt-1 text-xl font-semibold tracking-[-.035em]">Gasto acumulado</h2><div className="mt-5 h-[260px] min-w-0">{mounted && <ResponsiveContainer width="100%" height="100%"><AreaChart data={snapshot.trend.map((item) => ({ ...item, current: item.current / 100, previous: item.previous / 100 }))}><defs><linearGradient id="realFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#2bd9a8" stopOpacity=".35"/><stop offset="1" stopColor="#2bd9a8" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="#e5ece9"/><XAxis dataKey="day" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={(v) => `S/${v}`}/><ChartTooltip formatter={(value) => money(Number(value) * 100)}/><Area dataKey="previous" type="monotone" stroke="#bdc8c4" strokeDasharray="5 5" fill="none"/><Area dataKey="current" type="monotone" stroke="#20bb8c" strokeWidth={3} fill="url(#realFill)"/></AreaChart></ResponsiveContainer>}</div></section><section className="panel p-5 sm:p-6"><p className="section-label">Distribución</p><h2 className="mt-1 text-xl font-semibold tracking-[-.035em]">Por categoría</h2><div className="h-[210px]">{mounted && snapshot.byCategory.length > 0 && <ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={snapshot.byCategory} dataKey="value" innerRadius={58} outerRadius={84} stroke="none" paddingAngle={3}>{snapshot.byCategory.map((item, index) => <Cell key={item.name} fill={palette[index % palette.length]}/>)}</Pie><ChartTooltip formatter={(value) => money(Number(value))}/></PieChart></ResponsiveContainer>}</div><div className="space-y-2">{snapshot.byCategory.slice(0, 4).map((item, index) => <div key={item.name} className="flex items-center gap-2 text-sm"><span className="size-2.5 rounded-full" style={{ background: palette[index % palette.length] }}/><span className="flex-1 text-[#5d6e68]">{item.name}</span><strong>{money(item.value)}</strong></div>)}</div></section></div>}</>;
}

function BreakdownPanels({ bank, card, merchant = [] }: { bank: Array<{ name:string; value:number }>; card:Array<{ name:string; value:number }>; merchant?: Array<{ name:string; value:number }> }) {
  const panel = (title:string, items:Array<{name:string;value:number}>) => <section className="panel p-5 sm:p-6"><p className="section-label">Análisis</p><h2 className="mt-1 text-xl font-semibold tracking-[-.035em]">{title}</h2><div className="mt-5 space-y-4">{items.slice(0,5).map((item,index)=>{const max=items[0]?.value||1;return <div key={item.name}><div className="mb-1.5 flex items-center justify-between gap-4 text-sm"><span className="truncate text-[#5d6e68]">{item.name}</span><strong>{money(item.value)}</strong></div><div className="h-2 overflow-hidden rounded-full bg-[#edf2f0]"><div className="h-full rounded-full transition-[width] duration-500" style={{width:`${Math.max(4,(item.value/max)*100)}%`,background:palette[index%palette.length]}}/></div></div>})}{items.length===0&&<p className="text-sm text-[#7b8984]">Aún no hay datos en este periodo.</p>}</div></section>;
  return <div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{panel("Gastos por banco",bank)}{panel("Gastos por tarjeta",card)}{panel("Por comercio",merchant)}</div>;
}

function MonthPicker({ value, set, months }: { value: string; set: (v: string) => void; months: string[] }) {
  const now = currentMonthKey();
  const options = [...new Set([now, value, ...months])].sort().reverse();
  const shift = (delta: number) => { const [year, month] = value.split("-").map(Number); const next = new Date(year, month - 1 + delta, 1); set(`${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, "0")}`); };
  return <div className="flex shrink-0 items-center gap-0.5 rounded-xl border border-[#dce3e1] bg-white p-1" role="group" aria-label="Periodo mensual">
    <button type="button" aria-label="Mes anterior" onClick={() => shift(-1)} className="grid size-8 place-items-center rounded-lg text-[#4d5f59] hover:bg-[#f0f4f2]"><ChevronLeft className="size-4"/></button>
    <select aria-label="Mes y año" value={value} onChange={(event) => set(event.target.value)} className="h-8 max-w-[150px] bg-transparent px-1 text-sm font-semibold outline-none">{options.map((month) => <option key={month} value={month}>{monthLabel(month)}</option>)}</select>
    <button type="button" aria-label="Mes siguiente" disabled={value >= now} onClick={() => shift(1)} className="grid size-8 place-items-center rounded-lg text-[#4d5f59] hover:bg-[#f0f4f2] disabled:opacity-35 disabled:hover:bg-transparent"><ChevronRight className="size-4"/></button>
  </div>;
}

function RecurringPanel({ items }: { items: Recurring[] }) {
  return <section className="panel mt-4 p-5 sm:p-6"><p className="section-label">Recurrencia</p><h2 className="mt-1 text-xl font-semibold tracking-[-.035em]">Suscripciones y pagos recurrentes</h2><p className="mt-1 text-xs text-[#7b8984]">Se detectan con hasta 6 meses de historial; cada movimiento sigue en su mes.</p>
    {items.length === 0 ? <p className="mt-4 text-sm text-[#7b8984]">Aún no hay patrones recurrentes: se necesitan al menos 2 meses con el mismo comercio.</p> : <ul className="mt-4 divide-y divide-[#edf2f0]">{items.slice(0, 10).map((item) => <li key={`${item.merchant}-${item.currency}`} className="flex flex-wrap items-center justify-between gap-2 py-3">
      <div className="min-w-0"><p className="truncate font-semibold">{item.merchant}</p><p className="text-xs text-[#7b8984]">Visto en {item.months} meses{item.cadenceDays ? ` · cada ~${item.cadenceDays} días` : ""}{item.cardLabel ? ` · ${item.cardLabel}` : ""}{item.activeInPeriod ? "" : " · sin cobro este mes"}</p></div>
      <div className="flex items-center gap-3"><span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${item.kind === "subscription" ? "bg-[#e3f7ee] text-[#1e7a58]" : "bg-[#fff4d6] text-[#8a6410]"}`}>{item.kind === "subscription" ? "Suscripción" : "Posible recurrente"}</span><strong className="text-sm">≈ {money(item.medianCents, item.currency)} / mes</strong></div></li>)}</ul>}
  </section>;
}

function DashboardFilters({snapshot,period,setPeriod,bank,setBank,cardId,setCardId,categoryId,setCategoryId}:{snapshot:Snapshot;period:string;setPeriod:(v:string)=>void;bank:string;setBank:(v:string)=>void;cardId:string;setCardId:(v:string)=>void;categoryId:string;setCategoryId:(v:string)=>void}) {
  return <div className="mb-5 flex gap-2 overflow-x-auto pb-1"><MonthPicker value={period} set={setPeriod} months={snapshot.availableMonths ?? []}/><Select value={bank} set={setBank} aria-label="Banco"><option value="">Todos los bancos</option>{snapshot.banks.map((v)=><option key={v}>{v}</option>)}</Select><Select value={cardId} set={setCardId} aria-label="Tarjeta"><option value="">Todas las tarjetas</option>{snapshot.cards.map((v)=><option key={v.id} value={v.id}>{v.alias||`${v.brand} •••• ${v.last4}`}</option>)}</Select><Select value={categoryId} set={setCategoryId} aria-label="Categoría"><option value="">Todas las categorías</option>{snapshot.categories.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</Select></div>;
}

function TransactionsView({ snapshot, query, setQuery, period, setPeriod, bank, setBank, cardId, setCardId, categoryId, setCategoryId, add, edit, remove, sync }: { snapshot: Snapshot; query: string; setQuery: (v:string)=>void; period:string; setPeriod:(v:string)=>void; bank:string; setBank:(v:string)=>void; cardId:string; setCardId:(v:string)=>void; categoryId:string; setCategoryId:(v:string)=>void; add:()=>void; edit:(v:Transaction)=>void; remove:(id:string)=>void; sync:()=>void }) {
  return <><PageTitle eyebrow="Movimientos" title="Cada operación, bajo control." action={<Button onClick={add} className="rounded-xl"><Plus/>Nuevo movimiento</Button>}/><div className="panel mb-4 grid gap-2 p-3 sm:grid-cols-2 xl:grid-cols-[1fr_repeat(4,auto)]"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#87938f]"/><Input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder="Buscar comercio o descripción" className="h-10 rounded-xl pl-9 shadow-none"/></div><MonthPicker value={period} set={setPeriod} months={snapshot.availableMonths ?? []}/><Select value={bank} set={setBank}><option value="">Todos los bancos</option>{snapshot.banks.map((v)=><option key={v}>{v}</option>)}</Select><Select value={cardId} set={setCardId}><option value="">Todas las tarjetas</option>{snapshot.cards.map((v)=><option key={v.id} value={v.id}>{v.alias || `${v.brand} •••• ${v.last4}`}</option>)}</Select><Select value={categoryId} set={setCategoryId}><option value="">Todas las categorías</option>{snapshot.categories.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</Select></div>{snapshot.transactions.length === 0 ? <Empty className="panel min-h-[380px] border"><EmptyHeader><EmptyMedia variant="icon"><ListFilter/></EmptyMedia><EmptyTitle>No hay movimientos para estos filtros</EmptyTitle><EmptyDescription>Ajusta los filtros, sincroniza Gmail o registra un movimiento manual.</EmptyDescription></EmptyHeader><EmptyContent><div className="flex gap-2"><Button onClick={sync} variant="outline"><RefreshCw/>Sincronizar</Button><Button onClick={add}><Plus/>Agregar</Button></div></EmptyContent></Empty> : <section className="panel overflow-hidden"><div className="hidden md:block"><Table><TableHeader><TableRow className="bg-[#f8faf9]"><TableHead className="pl-6">Comercio</TableHead><TableHead>Banco / tarjeta</TableHead><TableHead>Categoría</TableHead><TableHead>Fecha</TableHead><TableHead className="text-right">Monto</TableHead><TableHead/></TableRow></TableHeader><TableBody>{snapshot.transactions.map((item)=><TableRow key={item.id}><TableCell className="pl-6"><strong>{item.merchant}</strong>{item.confidenceLevel === "medium" && <span title={item.decisionReason || "Confianza media"} className="ml-2 rounded-full bg-[#fff4d6] px-2 py-0.5 text-[10px] font-semibold text-[#8a6410]">Confianza media</span>}<p className="max-w-[220px] truncate text-xs text-[#82908b]">{item.description || (item.source === "gmail" ? "Importado desde Gmail" : "Registro manual")}</p></TableCell><TableCell><span>{item.bank}</span><p className="text-xs text-[#82908b]">{item.maskedCard || "Sin tarjeta"}</p></TableCell><TableCell><CategoryPill snapshot={snapshot} item={item}/></TableCell><TableCell>{dateText(item.operationDate)}</TableCell><TableCell className="text-right font-bold">{money(item.amountCents,item.currency)}</TableCell><TableCell><RowActions edit={()=>edit(item)} remove={()=>remove(item.id)} label={item.merchant}/></TableCell></TableRow>)}</TableBody></Table></div><div className="divide-y md:hidden">{snapshot.transactions.map((item)=><article key={item.id} className="p-4"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-[14px] bg-[#e7f4ee] text-xs font-black">{item.merchant.slice(0,2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate font-semibold">{item.merchant}</p><p className="mt-1 text-xs text-[#7d8b86]">{item.bank} · {dateText(item.operationDate)}</p></div><strong>{money(item.amountCents,item.currency)}</strong></div><div className="mt-3 flex items-center justify-between pl-[52px]"><CategoryPill snapshot={snapshot} item={item}/><RowActions edit={()=>edit(item)} remove={()=>remove(item.id)} label={item.merchant}/></div></article>)}</div></section>}</>;
}

function CardsView({ snapshot, add, edit, remove }: { snapshot:Snapshot; add:()=>void; edit:(v:Card)=>void; remove:(id:string)=>void }) { return <><PageTitle eyebrow="Tarjetas" title="Solo lo necesario. Nunca el número completo." action={<Button onClick={add} className="rounded-xl"><Plus/>Agregar tarjeta</Button>}/>{snapshot.cards.length === 0 ? <Empty className="panel min-h-[360px] border"><EmptyHeader><EmptyMedia variant="icon"><WalletCards/></EmptyMedia><EmptyTitle>Aún no hay tarjetas</EmptyTitle><EmptyDescription>Se crearán automáticamente al detectar alertas de Gmail. También puedes añadirlas usando solo los últimos cuatro dígitos.</EmptyDescription></EmptyHeader><EmptyContent><Button onClick={add}><Plus/>Agregar tarjeta</Button></EmptyContent></Empty> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{snapshot.cards.map((card,index)=><article key={card.id} className={`relative overflow-hidden rounded-[26px] p-6 text-white shadow-lg ${index%3===0?"bg-[#102820]":index%3===1?"bg-[#243c7c]":"bg-[#5b315f]"}`}><div className="flex items-start justify-between"><div><p className="text-xs text-white/55">{card.bank}</p><h3 className="mt-1 text-lg font-semibold">{card.alias || card.brand}</h3></div><CreditCard className="size-6 text-white/60"/></div><p className="mt-12 text-xl tracking-[.16em]">•••• {card.last4}</p><div className="mt-4 flex items-center justify-between text-xs text-white/55"><span>{card.cardType}</span><div className="flex gap-1"><button onClick={()=>edit(card)} className="rounded-lg p-2 hover:bg-white/10" aria-label="Editar"><Pencil className="size-4"/></button><ConfirmDelete label={card.alias || card.brand} onConfirm={()=>remove(card.id)}/></div></div></article>)}</div>}</> }

function AutomationView({ snapshot, addCategory, editCategory, removeCategory, addRule, editRule, removeRule, changeRule }: { snapshot:Snapshot; addCategory:()=>void; editCategory:(v:Category)=>void; removeCategory:(id:string)=>void; addRule:()=>void; editRule:(v:Rule)=>void; removeRule:(id:string)=>void; changeRule:(v:Rule,e:boolean)=>void }) { return <><PageTitle eyebrow="Automatización" title="Tu sistema aprende tus reglas."/><div className="grid gap-4 xl:grid-cols-2"><section className="panel p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="section-label">Organización</p><h2 className="mt-1 text-xl font-semibold">Categorías</h2></div><Button onClick={addCategory} variant="outline" size="sm"><Plus/>Nueva</Button></div><div className="mt-5 space-y-2">{snapshot.categories.map((item)=><div key={item.id} className="flex items-center gap-3 rounded-2xl border bg-[#fafcfb] p-3"><span className="size-3 rounded-full" style={{background:item.color}}/><span className="flex-1 font-medium">{item.name}</span><button onClick={()=>editCategory(item)} className="p-2 text-[#73817c]"><Pencil className="size-4"/></button>{item.name!=="Otros"&&<ConfirmDelete label={item.name} onConfirm={()=>removeCategory(item.id)}/>}</div>)}</div></section><section className="panel p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="section-label">Clasificación</p><h2 className="mt-1 text-xl font-semibold">Reglas automáticas</h2></div><Button onClick={addRule} variant="outline" size="sm"><Plus/>Nueva</Button></div><div className="mt-5 space-y-2">{snapshot.rules.map((rule)=><div key={rule.id} className="flex items-center gap-3 rounded-2xl border bg-[#fafcfb] p-3"><Switch checked={rule.enabled} onCheckedChange={(checked)=>changeRule(rule,checked)} aria-label={`Activar ${rule.name}`}/><div className="min-w-0 flex-1"><p className="truncate font-medium">{rule.name}</p><p className="truncate text-xs text-[#7b8984]">{rule.operator === "regex" ? "Coincide con" : "Contiene"} “{rule.pattern}”</p></div><button onClick={()=>editRule(rule)} className="p-2 text-[#73817c]"><Pencil className="size-4"/></button><ConfirmDelete label={rule.name} onConfirm={()=>removeRule(rule.id)}/></div>)}</div></section></div></> }

function SubcategoriesPanel({snapshot,add,edit,remove}:{snapshot:Snapshot;add:()=>void;edit:(v:Subcategory)=>void;remove:(id:string)=>void}) {
  return <section className="panel mt-4 p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="section-label">Detalle editable</p><h2 className="mt-1 text-xl font-semibold">Subcategorías</h2></div><Button onClick={add} variant="outline" size="sm"><Plus/>Nueva</Button></div>{snapshot.subcategories.length===0?<p className="mt-5 rounded-2xl bg-[#f3f7f5] p-4 text-sm text-[#6c7b76]">Crea subcategorías para separar, por ejemplo, supermercado y restaurantes dentro de Alimentación.</p>:<div className="mt-5 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{snapshot.subcategories.map((item)=>{const parent=snapshot.categories.find((category)=>category.id===item.categoryId);return <div key={item.id} className="flex items-center gap-3 rounded-2xl border bg-[#fafcfb] p-3"><span className="size-2.5 rounded-full" style={{background:parent?.color||"#8a9893"}}/><div className="min-w-0 flex-1"><p className="truncate font-medium">{item.name}</p><p className="truncate text-xs text-[#7b8984]">{parent?.name||"Sin categoría"}</p></div><button onClick={()=>edit(item)} className="p-2 text-[#73817c]" aria-label={`Editar ${item.name}`}><Pencil className="size-4"/></button><ConfirmDelete label={item.name} onConfirm={()=>remove(item.id)}/></div>})}</div>}</section>;
}

function EntityDialog({ modal, editing, snapshot, close, save }: { modal:Modal; editing:Transaction|Card|Category|Subcategory|Rule|null; snapshot:Snapshot; close:()=>void; save:(url:string,init:RequestInit,success:string)=>Promise<void> }) {
  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const values = Object.fromEntries(form.entries());
    if (modal === "transaction") { const item = editing as Transaction|null; const payload = { merchant: values.merchant, description: values.description || undefined, amount: Number(values.amount), currency: values.currency, operationDate: new Date(String(values.operationDate)+"T12:00:00").getTime(), operationType: values.operationType, bank: values.bank || "Manual", cardId: values.cardId || undefined, categoryId: values.categoryId || undefined, subcategoryId: values.subcategoryId || (item ? null : undefined) }; void save(item ? `/api/transactions/${item.id}` : "/api/transactions", { method:item?"PATCH":"POST", body:JSON.stringify(payload)}, item?"Movimiento actualizado":"Movimiento agregado"); }
    if (modal === "card") { const item = editing as Card|null; const payload = { bank:values.bank, brand:values.brand, last4:values.last4, cardType:values.cardType, alias:values.alias||undefined }; void save(item?`/api/cards/${item.id}`:"/api/cards",{method:item?"PATCH":"POST",body:JSON.stringify(payload)},item?"Tarjeta actualizada":"Tarjeta agregada"); }
    if (modal === "category") { const item=editing as Category|null; const payload={name:values.name,color:values.color,icon:"circle",kind:values.kind}; void save(item?`/api/categories/${item.id}`:"/api/categories",{method:item?"PATCH":"POST",body:JSON.stringify(payload)},item?"Categoría actualizada":"Categoría creada"); }
    if (modal === "subcategory") { const item=editing as Subcategory|null; const payload={name:values.name,categoryId:values.categoryId,parentCategoryId:values.categoryId}; void save(item?`/api/subcategories/${item.id}`:"/api/categories",{method:item?"PATCH":"POST",body:JSON.stringify(payload)},item?"Subcategoría actualizada":"Subcategoría creada"); }
    if (modal === "rule") { const item=editing as Rule|null; const payload={name:values.name,field:values.field,operator:values.operator,pattern:values.pattern,categoryId:values.categoryId,subcategoryId:values.subcategoryId||null,priority:Number(values.priority||100),enabled:item?.enabled??true}; void save(item?`/api/rules/${item.id}`:"/api/rules",{method:item?"PATCH":"POST",body:JSON.stringify(payload)},item?"Regla actualizada":"Regla creada"); }
  };
  const title = modal === "transaction" ? (editing?"Editar movimiento":"Nuevo movimiento") : modal === "card" ? (editing?"Editar tarjeta":"Agregar tarjeta") : modal === "category" ? (editing?"Editar categoría":"Nueva categoría") : modal === "subcategory" ? (editing?"Editar subcategoría":"Nueva subcategoría") : editing?"Editar regla":"Nueva regla";
  return <Dialog open={Boolean(modal)} onOpenChange={(open)=>{if(!open)close();}}><DialogContent className="rounded-[24px] sm:max-w-xl"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{modal === "card" ? "Solo almacenamos los últimos cuatro dígitos." : modal === "rule" ? "Las reglas se evalúan antes de la clasificación general." : "Todos los cambios se guardan en tu cuenta."}</DialogDescription></DialogHeader><form onSubmit={submit} className="grid gap-4">{modal === "transaction" && <TransactionFields item={editing as Transaction|null} snapshot={snapshot}/>} {modal === "card" && <CardFields item={editing as Card|null}/>} {modal === "category" && <CategoryFields item={editing as Category|null}/>} {modal === "subcategory" && <SubcategoryFields item={editing as Subcategory|null} categories={snapshot.categories}/>} {modal === "rule" && <RuleFields item={editing as Rule|null} categories={snapshot.categories} subcategories={snapshot.subcategories}/>}<DialogFooter><Button type="button" variant="outline" onClick={close}>Cancelar</Button><Button type="submit">Guardar</Button></DialogFooter></form></DialogContent></Dialog>;
}

function TransactionFields({ item, snapshot }: { item:Transaction|null; snapshot:Snapshot }) { return <div className="grid gap-4 sm:grid-cols-2"><Field label="Comercio" name="merchant" defaultValue={item?.merchant} required/><Field label="Monto" name="amount" type="number" step="0.01" defaultValue={item ? item.amountCents/100 : undefined} required/><label className="field-label">Moneda<Select name="currency" defaultValue={item?.currency||"PEN"}><option>PEN</option><option>USD</option></Select></label><label className="field-label">Fecha<FieldBare name="operationDate" type="date" defaultValue={inputDate(item?.operationDate)} required/></label><label className="field-label">Tipo<Select name="operationType" defaultValue={item?.operationType||"expense"}><option value="expense">Gasto</option><option value="subscription">Suscripción</option><option value="refund">Reembolso</option><option value="transfer">Transferencia</option><option value="income">Ingreso</option></Select></label><Field label="Banco" name="bank" defaultValue={item?.bank||"Manual"}/><label className="field-label">Tarjeta<Select name="cardId" defaultValue={item?.cardId||""}><option value="">Sin tarjeta</option>{snapshot.cards.map((v)=><option key={v.id} value={v.id}>{v.alias||`${v.brand} •••• ${v.last4}`}</option>)}</Select></label><label className="field-label">Categoría<Select name="categoryId" defaultValue={item?.categoryId||""}><option value="">Clasificar automáticamente</option>{snapshot.categories.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</Select></label><label className="field-label">Subcategoría<Select name="subcategoryId" defaultValue={item?.subcategoryId||""}><option value="">Sin subcategoría</option>{snapshot.subcategories.map((v)=><option key={v.id} value={v.id}>{snapshot.categories.find((c)=>c.id===v.categoryId)?.name} · {v.name}</option>)}</Select></label><div className="sm:col-span-2"><Field label="Descripción" name="description" defaultValue={item?.description||""}/></div></div>; }
function CardFields({ item }: { item:Card|null }) { return <div className="grid gap-4 sm:grid-cols-2"><Field label="Banco" name="bank" defaultValue={item?.bank} required disabled={Boolean(item)}/><Field label="Marca" name="brand" defaultValue={item?.brand||"VISA"} required/><Field label="Últimos 4 dígitos" name="last4" pattern="\d{4}" maxLength={4} defaultValue={item?.last4} required disabled={Boolean(item)}/><label className="field-label">Tipo<Select name="cardType" defaultValue={item?.cardType||"Crédito"}><option>Crédito</option><option>Débito</option></Select></label><div className="sm:col-span-2"><Field label="Alias" name="alias" defaultValue={item?.alias||""} placeholder="Ej. Compras diarias"/></div></div>; }
function CategoryFields({ item }: { item:Category|null }) { return <div className="grid gap-4 sm:grid-cols-[1fr_120px]"><Field label="Nombre" name="name" defaultValue={item?.name} required/><label className="field-label">Color<FieldBare name="color" type="color" defaultValue={item?.color||"#2bd9a8"}/></label><label className="field-label sm:col-span-2">Tipo<Select name="kind" defaultValue={item?.kind||"expense"}><option value="expense">Gastos</option><option value="income">Ingresos</option><option value="both">Ambos</option></Select></label></div>; }
function SubcategoryFields({item,categories}:{item:Subcategory|null;categories:Category[]}) { return <div className="grid gap-4"><Field label="Nombre" name="name" defaultValue={item?.name} required/><label className="field-label">Categoría principal<Select name="categoryId" defaultValue={item?.categoryId||categories[0]?.id} required>{categories.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</Select></label></div>; }
function RuleFields({ item, categories, subcategories }: { item:Rule|null; categories:Category[]; subcategories:Subcategory[] }) { return <div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre" name="name" defaultValue={item?.name} required/><label className="field-label">Campo<Select name="field" defaultValue={item?.field||"merchant"}><option value="merchant">Comercio</option><option value="description">Descripción</option></Select></label><label className="field-label">Condición<Select name="operator" defaultValue={item?.operator||"contains"}><option value="contains">Contiene</option><option value="equals">Es igual a</option><option value="starts_with">Empieza con</option><option value="regex">Expresión regular</option></Select></label><Field label="Texto o patrón" name="pattern" defaultValue={item?.pattern} required/><label className="field-label">Categoría<Select name="categoryId" defaultValue={item?.categoryId||categories[0]?.id}>{categories.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</Select></label><label className="field-label">Subcategoría<Select name="subcategoryId" defaultValue={item?.subcategoryId||""}><option value="">Sin subcategoría</option>{subcategories.map((v)=><option key={v.id} value={v.id}>{categories.find((c)=>c.id===v.categoryId)?.name} · {v.name}</option>)}</Select></label><Field label="Prioridad" name="priority" type="number" min="1" max="1000" defaultValue={item?.priority||100}/></div>; }

function Brand(){return <Link href="/" className="flex items-center gap-3 px-2"><span className="grid size-10 place-items-center rounded-[14px] bg-[#c9ff4d] text-[#102820]"><Sparkles className="size-5"/></span><span><strong className="block tracking-[-.03em]">Lúmina</strong><small className="text-white/45">Finanzas personales</small></span></Link>}
function Nav({active,icon,label,onClick}:{active:boolean;icon:React.ReactNode;label:string;onClick:()=>void}){return <button onClick={onClick} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium ${active?"bg-white text-[#102820]":"text-white/60 hover:bg-white/10 hover:text-white"}`}><span className="[&_svg]:size-[18px]">{icon}</span>{label}</button>}
function Bottom({active,icon,label,onClick}:{active:boolean;icon:React.ReactNode;label:string;onClick:()=>void}){return <button onClick={onClick} className={`flex min-h-14 flex-col items-center justify-center gap-1 rounded-[16px] text-[10px] ${active?"bg-white text-[#102820]":"text-white/55"}`}><span className="[&_svg]:size-5">{icon}</span>{label}</button>}
function Kpi({label,value,note,positive,icon}:{label:string;value:string;note:string;positive?:boolean;icon:React.ReactNode}){return <article className="panel p-5"><div className="flex items-start justify-between"><p className="text-sm font-medium text-[#71807b]">{label}</p><span className="grid size-9 place-items-center rounded-xl bg-[#edf3f0] text-[#476158] [&_svg]:size-[18px]">{icon}</span></div><p className="mt-4 text-[1.7rem] font-bold tracking-[-.05em]">{value}</p><p className={`mt-2 text-xs ${positive?"font-semibold text-[#16865e]":"text-[#84908c]"}`}>{note}</p></article>}
function PageTitle({eyebrow,title,action}:{eyebrow:string;title:string;action?:React.ReactNode}){return <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="section-label">{eyebrow}</p><h1 className="mt-1 text-3xl font-semibold tracking-[-.055em] sm:text-5xl">{title}</h1></div>{action}</div>}
function CategoryPill({snapshot,item}:{snapshot:Snapshot;item:Transaction}){const cat=snapshot.categories.find((v)=>v.id===item.categoryId);return <span className="inline-flex items-center gap-1.5 rounded-full bg-[#edf3f0] px-2.5 py-1 text-xs font-semibold"><span className="size-2 rounded-full" style={{background:cat?.color||"#8a9893"}}/>{cat?.name||item.category}</span>}
function RowActions({edit,remove,label}:{edit:()=>void;remove:()=>void;label:string}){return <div className="flex justify-end gap-1"><button onClick={edit} className="rounded-lg p-2 text-[#6d7c77] hover:bg-[#edf3f0]" aria-label={`Editar ${label}`}><Pencil className="size-4"/></button><ConfirmDelete label={label} onConfirm={remove}/></div>}
function ConfirmDelete({label,onConfirm}:{label:string;onConfirm:()=>void}){return <AlertDialog><AlertDialogTrigger asChild><button className="rounded-lg p-2 text-[#a34e43] hover:bg-[#faece9]" aria-label={`Eliminar ${label}`}><Trash2 className="size-4"/></button></AlertDialogTrigger><AlertDialogContent className="rounded-[22px]"><AlertDialogHeader><AlertDialogTitle>¿Eliminar “{label}”?</AlertDialogTitle><AlertDialogDescription>Esta acción no se puede deshacer.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction variant="destructive" onClick={onConfirm}>Eliminar</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
function Field({label,...props}:React.ComponentProps<"input">&{label:string}){return <label className="field-label">{label}<FieldBare {...props}/></label>}
function FieldBare(props:React.ComponentProps<"input">){return <Input {...props} className="mt-1 h-10 rounded-xl shadow-none"/>}
function Select({children,set,...props}:{children:React.ReactNode;set?:(v:string)=>void}&Omit<React.ComponentProps<"select">,"size">){return <NativeSelect {...props} onChange={(e)=>{props.onChange?.(e);set?.(e.target.value)}} className="mt-1 h-10 w-full min-w-[140px] rounded-xl bg-white shadow-none">{children}</NativeSelect>}
function AppSkeleton(){return <div className="min-h-screen bg-[#eef2f4] p-5 lg:pl-[270px]"><div className="mx-auto max-w-6xl space-y-5"><Skeleton className="h-14 w-72"/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[1,2,3,4].map(v=><Skeleton key={v} className="h-36 rounded-[24px]"/>)}</div><div className="grid gap-4 xl:grid-cols-[1.5fr_.8fr]"><Skeleton className="h-[380px] rounded-[24px]"/><Skeleton className="h-[380px] rounded-[24px]"/></div></div></div>}
function FatalState({online,message,retry}:{online:boolean;message:string;retry:()=>void}){return <main className="grid min-h-screen place-items-center bg-[#eef2f4] px-5 text-center"><div className="max-w-md"><span className="mx-auto grid size-14 place-items-center rounded-[20px] bg-[#102820] text-[#c9ff4d]">{online?<X className="size-6"/>:<CloudOff className="size-6"/>}</span><h1 className="mt-6 text-3xl font-semibold tracking-[-.05em]">{online?"No pudimos cargar tus datos":"Estás sin conexión"}</h1><p className="mt-3 leading-7 text-[#66766f]">{online?message:"Por seguridad, los datos financieros no se guardan en la caché."}</p><Button onClick={retry} className="mt-6 rounded-xl">Reintentar</Button></div></main>}
